51|# Build HTML
52|def esc(text):
53|    """Escape HTML entities."""
54|    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
55|
56|def md_to_html(text):
57|    """Simple markdown to HTML conversion."""
58|    result = []
59|    in_list = False
60|    
61|    for line in text.split('\n'):
62|        stripped = line.strip()
63|        
64|        # Empty line
65|        if not stripped:
66|            if in_list:
67|                result.append('</ul>')
68|                in_list = False
69|            result.append('')
70|            continue
71|        
72|        # Headers
73|        if stripped.startswith('### '):
74|            if in_list:
75|                result.append('</ul>')
76|                in_list = False
77|            result.append(f'<h3>{esc(stripped[4:])}</h3>')
78|            continue
79|        if stripped.startswith('#### '):
80|            if in_list:
81|                result.append('</ul>')
82|                in_list = False
83|            result.append(f'<h4>{esc(stripped[5:])}</h4>')
84|            continue
85|        
86|        # Bold/italic markers
87|        # **text** → <strong>text</strong>
88|        # *text* → <em>text</em>
89|        def format_inline(t):
90|            t = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', t)
91|            t = re.sub(r'\*(.+?)\*', r'<em>\1</em>', t)
92|            return t
93|        
94|        # List items
95|        if stripped.startswith('- '):
96|            if not in_list:
97|                result.append('<ul>')
98|                in_list = True
99|            result.append(f'<li>{format_inline(esc(stripped[2:]))}</li>')
100|            continue
101|        
102|        if stripped.startswith('* '):
103|            if not in_list:
104|                result.append('<ul>')
105|                in_list = True
106|            result.append(f'<li>{format_inline(esc(stripped[2:]))}</li>')
107|            continue
108|        
109|        # Numbered list items
110|        if re.match(r'^\d+\.\s', stripped):
111|            if not in_list:
112|                result.append('<ol>')
113|                in_list = True
114|            content = re.sub(r'^\d+\.\s', '', stripped)
115|            result.append(f'<li>{format_inline(esc(content))}</li>')
116|            continue
117|        
118|        # Close list if we were in one
119|        if in_list:
120|            result.append('</ul>' if not stripped[0].isdigit() else '</ol>')
121|            in_list = False
122|        
123|        # Normal paragraph — handle em dashes and quotes
124|        para = format_inline(esc(stripped))
125|        # Em dash fix: space-dash-space or double dash
126|        para = para.replace(' . ', ' — ')
127|        para = para.replace(' .', '—')
128|        result.append(f'<p>{para}</p>')
129|    
130|    if in_list:
131|        result.append('</ul>')
132|    
133|    return '\n'.join(result)
